import test from 'node:test';import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';
import {visualApplicable,aggregate} from './agent-workflows-gate.mjs';
const workflow=()=>readFileSync(new URL('./workflows/agent-evidence.yml',import.meta.url),'utf8');
const workflowFile=name=>readFileSync(new URL(`./workflows/${name}`,import.meta.url),'utf8');
test('docs applicability and shared tokens are explicit and conservative',()=>{assert.equal(visualApplicable(['docs/readme.md']),false);for(const p of ['frontend/src/design-system/tokens.css','frontend/src/page.test.ts','e2e/visual/scenarios.ts','.github/workflows/agent-evidence.yml'])assert.equal(visualApplicable([p]),true);assert.throws(()=>visualApplicable(null),/paths/);});
test('aggregate rejects missing cancelled skipped or failing required jobs',()=>{const n={changes:{result:'success',outputs:{visual:'false'}},validators:{result:'success'},visual:{result:'skipped'}};assert.equal(aggregate(n).ok,true);for(const status of ['cancelled','failure','skipped',undefined])assert.equal(aggregate({...n,validators:{result:status}}).ok,false);for(const status of ['cancelled','failure','skipped',undefined])assert.equal(aggregate({...n,changes:{result:'success',outputs:{visual:'true'}},visual:{result:status}}).ok,false);assert.equal(aggregate({...n,changes:{result:'failure',outputs:{visual:'false'}}}).ok,false);assert.equal(aggregate({...n,changes:{result:'success',outputs:{}}}).ok,false);});
test('self-hosted validation and visual checks are limited to ready same-repository PRs',()=>{const w=workflow();assert.match(w,/on:\n  pull_request:/);for(const job of ['changes','validators','aggregate','visual']){const section=w.match(new RegExp(`${job}:\\n([\\s\\S]*?)(?=\\n  [a-z-]+:|$)`))?.[1]??'';assert.match(section,/runs-on: \$\{\{ github\.event\.pull_request\.head\.repo\.full_name == github\.repository && !github\.event\.pull_request\.draft/);assert.ok(section.includes('"self-hosted","e2e","Windows"'));assert.ok(section.includes("|| 'ubuntu-24.04'"));}const visual=w.match(/  visual:\n([\s\S]*?)(?=\n  aggregate:|$)/)?.[1]??'';assert.match(visual,/runner\.os == 'Windows'/);assert.match(visual,/playwright install chromium/);assert.match(visual,/playwright install --with-deps chromium/);assert.match(w,/permissions:\n  contents: read/);assert.doesNotMatch(w,/pull_request_target|secrets\.|contents: write|pull-requests: write/);assert.doesNotMatch(w,/^    paths:/m);for(const action of w.matchAll(/uses: ([^\s]+)/g))assert.match(action[1],/@[a-f0-9]{40}$/);assert.match(w,/persist-credentials: false/);assert.match(w,/ref: \$\{\{ github\.event\.pull_request\.head\.sha \}\}/);});
test('stable gate always runs and visual reports upload even on failure',()=>{const w=workflow();assert.match(w,/name: Agent workflow gate/);assert.match(w,/aggregate:\n    name: Agent workflow gate\n    if: \$\{\{ always\(\) \}\}/);assert.match(w,/needs: \[changes, validators, visual\]/);assert.match(w,/id: evidence\n        if: \$\{\{ always\(\) \}\}/);assert.match(w,/if-no-files-found: error/);assert.match(w,/STOVO_VISUAL_COMPARE: 'true'/);assert.match(w,/STOVO_VISUAL_COMPARE=false node e2e\/tools\/capture-evidence\.mjs/);assert.match(w,/Windows screenshot candidates were captured/);assert.match(w,/compare-revisions\.mjs/);assert.match(w,/npm --prefix frontend ci/);assert.match(w,/playwright install --with-deps chromium/);assert.doesNotMatch(w,/run-evals\.mjs/);});
test('visual evidence retries transient Chromium download failures on both platforms',()=>{const w=workflow();assert.match(w,/for attempt in 1 2 3/);assert.match(w,/install_command=\(npx playwright install chromium\)/);assert.match(w,/install_command=\(npx playwright install --with-deps chromium\)/);assert.match(w,/if "\$\{install_command\[@\]\}"; then/);assert.match(w,/if \[ "\$attempt" -eq 3 \]; then exit 1; fi/);});
test('trusted documentation and CodeQL jobs use online Windows runners',()=>{for(const name of ['docs-validation.yml','codeql.yml']){const w=workflowFile(name);assert.match(w,/self-hosted.*Windows.*tests/);assert.match(w,/ubuntu-latest/);assert.doesNotMatch(w,/self-hosted.*Linux.*tests/);}const docs=workflowFile('docs-validation.yml');assert.match(docs,/helm-\$version-windows-amd64\.zip/);const codeql=workflowFile('codeql.yml');assert.match(codeql,/setup-go@/);assert.match(codeql,/gradlew\.bat/);});
test('frontend fixes require screenshot evidence in agent instructions',()=>{const instructions=readFileSync(new URL('../AGENTS.md',import.meta.url),'utf8');assert.match(instructions,/frontend fix[\s\S]*screenshot/i);});
test('cross-platform size baseline covers the Windows mock API line count',()=>{const baseline=readFileSync(new URL('../docs/engineering/size-baseline.tsv',import.meta.url),'utf8');assert.match(baseline,/^frontend\/src\/dev\/mockApi\.ts\t418$/m);});
